import { z } from "zod";
import { feedAuthorSchema } from "../activities/feed.js";

/** A comment's body (ADR-034 §2): plain text, 1 to 1,000 characters once trimmed. */
export const commentBodySchema = z.string().trim().min(1).max(1000);

/** `POST /v1/activities/:id/comments` body (ADR-034 §3): the id is generated by the app. */
export const createCommentRequestSchema = z.object({
  id: z.uuid(),
  body: commentBodySchema,
});
export type CreateCommentRequest = z.infer<typeof createCommentRequestSchema>;

/** `PATCH /v1/activities/:id/comments/:commentId` body (ADR-034 §3). */
export const updateCommentRequestSchema = z.object({ body: commentBodySchema });
export type UpdateCommentRequest = z.infer<typeof updateCommentRequestSchema>;

/** One comment of an Activity (ADR-034 §3). Deleted comments are never returned. */
export const commentSchema = z.object({
  id: z.uuid(),
  body: z.string(),
  createdAt: z.iso.datetime(),
  /** Set when the comment was edited ("modifié"), null otherwise. */
  updatedAt: z.iso.datetime().nullable(),
  author: feedAuthorSchema,
  /** The viewer wrote the comment. */
  viewerCanEdit: z.boolean(),
  /** The viewer wrote the comment or the Activity. */
  viewerCanDelete: z.boolean(),
});
export type ActivityComment = z.infer<typeof commentSchema>;

/**
 * `GET /v1/activities/:id/comments` query (ADR-034 §3): without `before`,
 * the newest page; `before` is the opaque `previousCursor` of a page to
 * load the comments older than it.
 */
export const listCommentsQuerySchema = z.object({
  before: z.string().min(1).max(200).optional(),
  limit: z.coerce.number().int().min(1).max(50).default(50),
});
export type ListCommentsQuery = z.infer<typeof listCommentsQuerySchema>;

/** A page of comments in chronological order; `previousCursor` is null when there are no older ones. */
export const listCommentsResponseSchema = z.object({
  items: z.array(commentSchema),
  previousCursor: z.string().min(1).nullable(),
});
export type ListCommentsResponse = z.infer<typeof listCommentsResponseSchema>;
